/**
 * Build a demo dataset that the dashboards can measure honestly.
 *
 * The problem this replaces: `seed.ts` wrote ninety-five conversations with no
 * messages, a `rand()` sentiment and a `rand()` topic. Every Insights panel
 * then reported on fixtures — "What guests ask about" was 6/101 real, "Team
 * load" was 0/115 real, and the sentiment pie was dice. A demo built on that
 * shows a customer a picture of nothing.
 *
 * THE RULE HERE: this script does not write conversation content. It drives the
 * real HTTP API, so every reply is generated by the real agent, every sentiment
 * label comes from the real classifier, every task is raised by the real
 * escalation paths, and every latency is a measured one. What the dashboards
 * then show is the product's own behaviour.
 *
 * THE ONE EXCEPTION, stated plainly: timestamps are moved afterwards to spread
 * the conversations across fourteen days, because a chart of "the last 14 days"
 * is useless when everything happened in one afternoon. The words, the labels,
 * the tasks and the durations are all genuine; only when they happened is
 * arranged. Nothing else is invented.
 *
 * Requires the dev server on :5000 and Ollama up. Takes 10-20 minutes — every
 * turn is a real model call on one GPU.
 *
 *   npx tsx scripts/build-demo-data.ts            # dry run: show the plan
 *   npx tsx scripts/build-demo-data.ts --apply
 *   npx tsx scripts/build-demo-data.ts --purge    # remove demo data only
 */
import "dotenv/config";
import Database from "better-sqlite3";

const BASE = process.env.DEMO_BASE || "http://localhost:5000";
const TOKEN = process.env.STAFF_API_TOKEN || "";
const APPLY = process.argv.includes("--apply");
const PURGE = process.argv.includes("--purge");

/* Marks every row this script owns, so a re-run can clear its own work without
   touching the eight original demo guests or anything a human typed. */
const TAG = "[demo-cohort]";

const db = new Database(process.env.DB_FILE || "data.db");
db.pragma("busy_timeout = 8000");

const api = async (path: string, init?: RequestInit) => {
  const r = await fetch(`${BASE}${path}`, {
    ...init,
    headers: { "Content-Type": "application/json", "x-staff-token": TOKEN, ...(init?.headers ?? {}) },
  });
  if (!r.ok) throw new Error(`${init?.method ?? "GET"} ${path} -> ${r.status} ${await r.text()}`);
  return r.json();
};

