/* ------------------------------------------------------------------ purge */

function purge() {
  const ids = (db.prepare(`SELECT id FROM guests WHERE notes LIKE '%${TAG}%'`).all() as any[]).map((r) => r.id);
  if (!ids.length) return console.log("khong co du lieu demo de xoa.");
  const convIds = (
    db.prepare(`SELECT id FROM conversations WHERE guest_id IN (${ids.join(",")})`).all() as any[]
  ).map((r) => r.id);
  db.transaction(() => {
    if (convIds.length) {
      for (const t of ["messages", "tasks", "trace_spans", "audit_events", "guest_requests", "service_approvals", "feedback"]) {
        db.prepare(`DELETE FROM ${t} WHERE conversation_id IN (${convIds.join(",")})`).run();
      }
      db.prepare(`DELETE FROM conversations WHERE id IN (${convIds.join(",")})`).run();
    }
    db.prepare(`DELETE FROM reservations WHERE guest_id IN (${ids.join(",")})`).run();
    db.prepare(`DELETE FROM guests WHERE id IN (${ids.join(",")})`).run();
  })();
  console.log(`da xoa ${ids.length} khach demo, ${convIds.length} hoi thoai.`);
}

/* Fixtures are the reason the dashboards were meaningless — remove them so
   every panel is computed over conversations that actually contain words. */
function purgeFixtures() {
  const ids = (
    db.prepare("SELECT id FROM conversations WHERE sentiment_source = 'seed'").all() as any[]
  ).map((r) => r.id);
  if (!ids.length) return console.log("khong con fixture seed.");
  db.transaction(() => {
    for (const t of ["messages", "tasks", "trace_spans", "audit_events", "guest_requests", "service_approvals", "feedback"]) {
      db.prepare(`DELETE FROM ${t} WHERE conversation_id IN (${ids.join(",")})`).run();
    }
    db.prepare(`DELETE FROM conversations WHERE id IN (${ids.join(",")})`).run();
    /* Seeded tasks with no conversation at all are the same fiction by another
       route: nothing raised them, and a manager clicking one cannot open the
       thread behind it because there is none. Kept once with an exception for
       `source='staff'`, which was a mistake — those 42 rows carried creation
       dates from seed time, so closing them stamped a resolution days later and
       dragged average resolution time to 5,322 minutes. Every task now traces
       to a conversation somebody actually had. */
    db.prepare("DELETE FROM tasks WHERE conversation_id IS NULL").run();
  })();
  console.log(`da xoa ${ids.length} hoi thoai fixture (sentiment_source='seed').`);
}

