console.log(`  gui ${turns} luot khach qua API THAT -> agent that tra loi, head that cham cam xuc`);
console.log(`  ${COHORT.filter((p) => p.turns.some((t) => t.staffReply)).length} hoi thoai co nhan vien tra loi`);
console.log(`  sau do: giao + dong mot phan task qua API, roi doi timestamp trai deu 14 ngay`);
